340	    // ============================ 夜间接力押运 ============================
341	
342	    /**
343	     * 设置安全接力点（创建进行中接力段）。
344	     * 约束：途经点计划通过时刻须严格早于夜间禁行起点；运单+途经点序号去重；
345	     * 同一运单同时刻只允许一个进行中接力段（占用表主键冲突即 409）。
346	     */
347	    public ServiceResult setRelayPoint(String shipmentNo, RelayPointRequest request) {
348	        String fingerprint = fingerprint("RELAY_POINT", request.requestId(), shipmentNo,
349	                String.valueOf(request.waypointSeq()));
350	        return withIdempotency(request.requestId(), fingerprint,
351	                () -> tx.execute(status -> doSetRelayPoint(shipmentNo, request)));
352	    }
353	
354	    private ServiceResult doSetRelayPoint(String shipmentNo, RelayPointRequest request) {
355	        Shipment shipment = loadShipment(shipmentNo);
356	        repository.lockShipment(shipment.id());
357	        shipment = repository.findShipmentById(shipment.id()).orElseThrow();
358	        if (shipment.status().isTerminal()) {
359	            throw ApiException.conflict("SHIPMENT_TERMINAL",
360	                    "运单终态 " + shipment.status() + "，不可设置接力点");
361	        }
362	        if (shipment.status() == ShipmentStatus.APPLIED) {
363	            throw ApiException.conflict("INVALID_STATUS", "运单尚未核准路线，不可设置接力点");
364	        }
365	        RouteApproval approval = currentApproval(shipment);
366	        List<ApprovalWaypoint> waypoints = repository.findWaypoints(approval.id());
367	        ApprovalWaypoint target = waypoints.stream()
368	                .filter(w -> w.seq() == request.waypointSeq()).findFirst()
369	                .orElseThrow(() -> ApiException.badRequest("WAYPOINT_NOT_FOUND",
370	                        "当前路线无途经点序号 " + request.waypointSeq()));
371	        NightCurfew curfew = applicableCurfew(shipment, waypoints);
372	        if (curfew != null && !target.plannedTime().isBefore(curfew.curfewStart())) {
373	            throw ApiException.badRequest("RELAY_POINT_UNSAFE",
374	                    "途经点 " + target.seq() + " 计划通过时刻 " + target.plannedTime()
375	                            + " 不早于夜间禁行起点 " + curfew.curfewStart() + "，不能作为安全接力点");
376	        }
377	        if (repository.findSegment(shipment.id(), approval.id(), target.seq()).isPresent()) {
378	            throw ApiException.conflict("RELAY_POINT_DUPLICATE",
379	                    "途经点 " + target.seq() + " 已设置接力段（运单+途经点序号去重）");
380	        }
381	        LocalDateTime now = now();
382	        long segmentId;
383	        try {
384	            segmentId = repository.insertRelaySegment(shipment.id(), approval.id(), target.seq(), now);
385	        } catch (DuplicateKeyException e) {
386	            throw ApiException.conflict("RELAY_POINT_DUPLICATE",
387	                    "途经点 " + target.seq() + " 已设置接力段（运单+途经点序号去重）");
388	        }
389	        try {
390	            // 主键冲突即并发占用失败：同一运单同时刻只允许一个进行中接力段。
391	            repository.occupyRelay(shipment.id(), segmentId);
392	        } catch (DuplicateKeyException e) {
393	            throw ApiException.conflict("RELAY_SEGMENT_ACTIVE",
394	                    "同一运单同时刻只允许一个进行中接力段");
395	        }
396	        repository.insertEvent(shipment.id(), EVT_RELAY_POINT_SET,
397	                "设置安全接力点：途经点 " + target.seq() + "(" + target.name() + ")，计划通过 "
398	                        + target.plannedTime(), now);
399	        Map<String, Object> body = shipmentView(shipmentNo);
400	        body.put("relaySegmentId", segmentId);
401	        return ServiceResult.ok(body);
402	    }
403	
404	    /**
405	     * 接力双人打卡：交班（OUT）与接班（IN）各一条，双方编号须不同（单人打卡不生效）；
406	     * 接班时刻须严格晚于交班时刻，否则逆序拒绝并告警；双方齐全即完成换班并释放接力段占用。
407	     */
408	    public ServiceResult relayCheckin(String shipmentNo, RelayCheckinRequest request) {
409	        String fingerprint = fingerprint("RELAY_CHECKIN", request.requestId(), shipmentNo,
410	                request.escortId(), request.role(), request.checkTime().toString());
411	        return withIdempotency(request.requestId(), fingerprint,
412	                () -> tx.execute(status -> doRelayCheckin(shipmentNo, request)));
413	    }
414	
415	    private ServiceResult doRelayCheckin(String shipmentNo, RelayCheckinRequest request) {
416	        EscortRole role = EscortRole.parse(request.role());
417	        if (role == null) {
418	            throw ApiException.badRequest("INVALID_ROLE",
419	                    "打卡角色须为 OUT（交班）或 IN（接班）: " + request.role());
420	        }
421	        Shipment shipment = loadShipment(shipmentNo);
422	        // 行锁串行化换班完成与禁行冻结的并发终态竞争。
423	        repository.lockShipment(shipment.id());
424	        shipment = repository.findShipmentById(shipment.id()).orElseThrow();
425	        LocalDateTime now = now();
426	        if (shipment.status().isTerminal()) {
427	            throw ApiException.conflict("SHIPMENT_TERMINAL",
428	                    "运单终态 " + shipment.status() + "，不可接力打卡");
429	        }
430	        if (shipment.status() != ShipmentStatus.DISPATCHED && shipment.status() != ShipmentStatus.IN_TRANSIT) {
431	            throw ApiException.conflict("NOT_DISPATCHED",
432	                    "运单当前状态 " + shipment.status() + "，不可接力打卡");
433	        }
434	        // 恰满禁行起点即判超时：懒冻结（冻结与处置登记同一事务提交）后返回 409。
435	        if (freezeIfCurfewOverdue(shipment, now)) {
436	            return curfewFrozenResult(shipmentNo);
437	        }
438	        RelaySegment segment = repository.findActiveSegment(shipment.id())
439	                .orElseThrow(() -> ApiException.conflict("RELAY_SEGMENT_NOT_FOUND",
440	                        "运单无进行中接力段，请先设置安全接力点"));
441	        RouteApproval approval = currentApproval(shipment);
442	        NightCurfew curfew = applicableCurfew(shipment, repository.findWaypoints(approval.id()));
443	        if (curfew != null && !request.checkTime().isBefore(curfew.curfewStart())) {
444	            throw ApiException.badRequest("RELAY_CHECKIN_TOO_LATE",
445	                    "接力打卡时刻 " + request.checkTime() + " 须严格早于夜间禁行起点 " + curfew.curfewStart());
446	        }
447	        if (repository.findRelayCheckin(segment.id(), role).isPresent()) {
448	            throw ApiException.conflict("RELAY_CHECKIN_DUPLICATE",
449	                    "接力点 " + segment.relaySeq() + " 角色 " + role + " 已打卡（运单+途经点序号去重）");
450	        }
451	        Optional<RelayCheckin> outCk = repository.findRelayCheckin(segment.id(), EscortRole.OUT);
452	        Optional<RelayCheckin> inCk = repository.findRelayCheckin(segment.id(), EscortRole.IN);
453	        Optional<RelayCheckin> opposite = role == EscortRole.OUT ? inCk : outCk;
454	        if (opposite.isPresent() && opposite.get().escortId().equals(request.escortId())) {
455	            throw ApiException.badRequest("RELAY_SAME_ESCORT",
456	                    "交接班押运员编号相同（" + request.escortId() + "），单人打卡不生效");
457	        }
458	        // 时序校验：接班时刻须严格晚于交班时刻；乱序回传按时刻归位，逆序拒绝并告警。
459	        if (role == EscortRole.IN && outCk.isPresent()
460	                && !request.checkTime().isAfter(outCk.get().checkTime())) {
461	            rejectRelayReverse(shipment, segment, request,
462	                    "未晚于交班时刻 " + outCk.get().checkTime(), now);
463	        }
464	        if (role == EscortRole.OUT && inCk.isPresent()
465	                && !inCk.get().checkTime().isAfter(request.checkTime())) {
466	            rejectRelayReverse(shipment, segment, request,
467	                    "交班后已有接班时刻 " + inCk.get().checkTime() + " 不晚于本次交班时刻", now);
468	        }
469	        repository.insertRelayCheckin(segment.id(), shipment.id(), request.escortId(), role,
470	                request.checkTime(), request.requestId(), now);
471	
472	        Optional<RelayCheckin> outFinal = repository.findRelayCheckin(segment.id(), EscortRole.OUT);
473	        Optional<RelayCheckin> inFinal = repository.findRelayCheckin(segment.id(), EscortRole.IN);
474	        Map<String, Object> body;
475	        if (outFinal.isPresent() && inFinal.isPresent()) {
476	            RelayCheckin out = outFinal.get();
477	            RelayCheckin in = inFinal.get();
478	            int rows = repository.completeSegment(segment.id(), out.escortId(), out.checkTime(),
479	                    in.escortId(), in.checkTime(), in.checkTime());
480	            if (rows == 0) {
481	                throw ApiException.conflict("RELAY_SEGMENT_CLOSED", "接力段已被并发完成或冻结，请重试");
482	            }
483	            repository.releaseRelay(shipment.id());
484	            repository.insertEvent(shipment.id(), EVT_RELAY_HANDOVER,
485	                    "接力点 " + segment.relaySeq() + " 换班完成：交班 " + out.escortId() + "@"
486	                            + out.checkTime() + "，接班 " + in.escortId() + "@" + in.checkTime(), now);
487	            body = shipmentView(shipmentNo);
488	            body.put("handoverCompleted", true);
489	        } else {
490	            // 单人打卡不生效：仅记录一侧打卡，换班未完成。
491	            body = shipmentView(shipmentNo);
492	            body.put("handoverCompleted", false);
493	            body.put("message", "已记录 " + role + " 打卡，待对方打卡后换班生效（单人打卡不生效）");
494	        }
495	        return ServiceResult.ok(body);
496	    }
497	
498	    private void rejectRelayReverse(Shipment shipment, RelaySegment segment,
499	                                    RelayCheckinRequest request, String detail, LocalDateTime now) {
500	        String message = "接力点 " + segment.relaySeq() + " " + request.role() + " 打卡时刻 "
501	                + request.checkTime() + " " + detail + "，逆序拒绝";
502	        eventRecorder.recordNewTransaction(shipment.id(), EVT_RELAY_CHECKIN_REVERSED, message, now);
503	        throw ApiException.badRequest("RELAY_CHECKIN_REVERSED", message);
504	    }
505	
506	    // ============================ 夜间禁行判定与冻结 ============================
507	
508	    /**
509	     * 适用禁行规则：计划运输窗口（计划发运 → 最后途经点计划通过时刻）与禁行窗口
510	     * [curfewStart, curfewEnd) 相交（计划到达不早于禁行起点）时返回该规则，否则 null。
511	     */
512	    private NightCurfew applicableCurfew(Shipment shipment, List<ApprovalWaypoint> waypoints) {
513	        RouteApproval approval = currentApproval(shipment);
514	        List<NightCurfew> curfews = repository.findNightCurfews(approval.routeCode());
515	        if (curfews.isEmpty() || waypoints.isEmpty()) {
516	            return null;
517	        }
518	        LocalDateTime lastPlanned = waypoints.stream()
519	                .map(ApprovalWaypoint::plannedTime).max(LocalDateTime::compareTo).orElseThrow();
520	        for (NightCurfew curfew : curfews) {
521	            if (shipment.plannedDeparture().isBefore(curfew.curfewEnd())
522	                    && !lastPlanned.isBefore(curfew.curfewStart())) {
523	                return curfew;
524	            }
525	        }
526	        return null;
527	    }
528	
529	    /** 换班是否已在禁行起点前完成：存在 COMPLETED 接力段且完成时刻严格早于禁行起点。 */
530	    private boolean handoverCompletedBefore(long shipmentId, LocalDateTime curfewStart) {
531	        return repository.findSegments(shipmentId).stream()
532	                .anyMatch(s -> s.status() == RelaySegmentStatus.COMPLETED
533	                        && s.completedAt() != null && s.completedAt().isBefore(curfewStart));
534	    }
535	
536	    /**
537	     * 夜间禁行冻结判定与执行（须在事务内、已持有运单行锁后调用）。
538	     * 恰满禁行起点即判超时；冻结与处置登记在同一事务内完成；
539	     * 终态 CAS 保证与核销/失联竞争时形成唯一终态。返回 true 表示本次冻结成功。
540	     */
541	    private boolean freezeIfCurfewOverdue(Shipment shipment, LocalDateTime now) {
542	        if (shipment.status() != ShipmentStatus.DISPATCHED && shipment.status() != ShipmentStatus.IN_TRANSIT) {
543	            return false;
544	        }
545	        RouteApproval approval = currentApproval(shipment);
546	        List<ApprovalWaypoint> waypoints = repository.findWaypoints(approval.id());
547	        NightCurfew curfew = applicableCurfew(shipment, waypoints);
548	        if (curfew == null || now.isBefore(curfew.curfewStart())) {
549	            return false;
550	        }
551	        if (handoverCompletedBefore(shipment.id(), curfew.curfewStart())) {
552	            return false;
553	        }
554	        int rows = repository.compareAndSetTerminal(shipment.id(), ShipmentStatus.CURFEW_FROZEN);
555	        if (rows == 0) {
556	            // 终态竞争败者：核销/失联已先行，唯一终态。
557	            return false;
558	        }
559	        repository.freezeActiveSegments(shipment.id());
560	        Long segmentId = repository.findSegments(shipment.id()).stream()
561	                .filter(s -> s.status() == RelaySegmentStatus.FROZEN)
562	                .map(RelaySegment::id).findFirst().orElse(null);
563	        repository.releaseRelay(shipment.id());
564	        repository.releaseVehicle(shipment.vehiclePlate());
565	        String reason = "未在夜间禁行起点 " + curfew.curfewStart() + " 前完成押运换班，运单冻结并转处置";
566	        repository.insertDisposal(shipment.id(), segmentId, reason, curfew.curfewStart(), now);
567	        repository.insertEvent(shipment.id(), EVT_CURFEW_FROZEN, reason, now);
568	        return true;
569	    }
