587	    private ServiceResult doReroute(String shipmentNo, RerouteRequest request) {
588	        Shipment shipment = loadShipment(shipmentNo);
589	        if (shipment.status().isTerminal()) {
590	            throw ApiException.conflict("SHIPMENT_TERMINAL", "运单已终态，不可改线");
591	        }
592	        if (shipment.status() != ShipmentStatus.DISPATCHED && shipment.status() != ShipmentStatus.IN_TRANSIT) {
593	            throw ApiException.conflict("INVALID_STATUS", "仅发运后可紧急改线，当前 " + shipment.status());
594	        }
595	        repository.findRoute(request.routeCode())
596	                .orElseThrow(() -> ApiException.badRequest("ROUTE_NOT_FOUND",
597	                        "路线不存在: " + request.routeCode()));
598	        List<RouteApproval> approvals = repository.findApprovals(shipment.id());
599	        boolean pendingExists = approvals.stream()
600	                .anyMatch(a -> a.status() == RouteApprovalStatus.PENDING);
601	        if (pendingExists) {
602	            throw ApiException.conflict("REROUTE_PENDING", "已有待核准改线申请，请先完成核准");
603	        }
604	        int nextVersion = approvals.stream().mapToInt(RouteApproval::versionNo).max().orElse(0) + 1;
605	        LocalDateTime now = now();
606	        long newApprovalId = repository.insertApproval(shipment.id(), request.routeCode(), nextVersion,
607	                RouteApprovalStatus.PENDING, null, now);
608	        List<RouteWaypointDef> defs = repository.findWaypointDefs(request.routeCode());
609	        for (RouteWaypointDef def : defs) {
610	            repository.insertWaypoint(newApprovalId, shipment.id(), def.seq(), def.name(),
611	                    shipment.plannedDeparture().plusMinutes(def.offsetMinutes()), WaypointState.PENDING);
612	        }
613	        Map<String, Object> body = shipmentView(shipmentNo);
614	        body.put("pendingApprovalId", newApprovalId);
615	        body.put("message", "改线申请已提交，核准通过前原路线打卡继续有效");
616	        return ServiceResult.ok(body);
617	    }
