623	    private ServiceResult doApproveReroute(String shipmentNo, long approvalId) {
624	        Shipment shipment = loadShipment(shipmentNo);
625	        RouteApproval next = repository.findApproval(approvalId)
626	                .orElseThrow(() -> ApiException.notFound("APPROVAL_NOT_FOUND", "核准记录不存在"));
627	        if (next.shipmentId() != shipment.id()) {
628	            throw ApiException.badRequest("APPROVAL_MISMATCH", "核准记录不属于该运单");
629	        }
630	        if (next.status() != RouteApprovalStatus.PENDING || next.versionNo() <= 1) {
631	            throw ApiException.conflict("APPROVAL_NOT_PENDING", "该记录不是待核准改线申请");
632	        }
633	        LocalDateTime now = now();
634	        RouteRuleEvaluator.Result result = evaluate(next.routeCode(),
635	                shipment.goodsCategory(), shipment.plannedDeparture());
636	        if (!result.allowed()) {
637	            // 改线驳回仅落库新记录的驳回结果，原路线继续有效；提交后返回 422。
638	            repository.updateApprovalStatus(next.id(), RouteApprovalStatus.REJECTED, now);
639	            repository.insertEvent(shipment.id(), EVT_REROUTE_REJECTED, result.message(), now);
640	            Map<String, Object> body = shipmentView(shipmentNo);
641	            body.put("errorCode", "REROUTE_REJECTED");
642	            body.put("message", result.message());
643	            return ServiceResult.status(422, body);
644	        }
645	        // 同一事务：旧路线终止 + 新路线生效 + 运单指向切换。
646	        RouteApproval old = currentApproval(shipment);
647	        repository.updateApprovalStatus(old.id(), RouteApprovalStatus.TERMINATED, now);
648	        repository.updateApprovalStatus(next.id(), RouteApprovalStatus.APPROVED, now);
649	        repository.updateCurrentApproval(shipment.id(), next.id());
650	        if (shipment.status() == ShipmentStatus.DISPATCHED) {
651	            repository.updateStatus(shipment.id(), ShipmentStatus.IN_TRANSIT);
652	        }
653	        repository.insertEvent(shipment.id(), EVT_REROUTE_SWITCH,
654	                "路线由 " + old.routeCode() + "(v" + old.versionNo() + ") 切换为 "
655	                        + next.routeCode() + "(v" + next.versionNo() + ")，原路线打卡保留", now);
656	        return ServiceResult.ok(shipmentView(shipmentNo));
657	    }
