379	            "id, shipment_id, approval_id, relay_seq, status, out_escort_id, out_time, in_escort_id, in_time, created_at, completed_at";
380	
381	    public long insertRelaySegment(long shipmentId, long approvalId, int relaySeq, LocalDateTime now) {
