384	            PreparedStatement ps = connection.prepareStatement(
385	                    "INSERT INTO relay_segment (shipment_id, approval_id, relay_seq, status, out_escort_id, out_time, in_escort_id, in_time, created_at, completed_at) "
386	                            + "VALUES (?, ?, ?, 'IN_PROGRESS', NULL, NULL, NULL, NULL, ?, NULL)",
