408	    public Optional<RelaySegment> findActiveSegment(long shipmentId) {
409	        return jdbc.query("SELECT s." + SEGMENT_COLUMNS.replace(", ", ", s.") + " FROM relay_segment s "
410	                        + "JOIN shipment_active_relay a ON a.segment_id = s.id WHERE a.shipment_id = ?",
