415	    public int completeSegment(long segmentId, String outEscortId, LocalDateTime outTime,
416	                               String inEscortId, LocalDateTime inTime, LocalDateTime completedAt) {
417	        return jdbc.update("UPDATE relay_segment SET status = 'COMPLETED', out_escort_id = ?, out_time = ?, "
418	                        + "in_escort_id = ?, in_time = ?, completed_at = ? WHERE id = ? AND status = 'IN_PROGRESS'",
