15	/**
16	 * 夜间接力押运双人打卡：接力点设置、交接班双方编号与时刻、单人打卡不生效、
17	 * 乱序回传按时刻归位、逆序拒绝并告警、运单+途经点序号去重、requestId 幂等。
18	 *
19	 * <p>场景：R-G3 夜间禁行 2026-10-03 00:00~05:00；运单 2026-10-02 22:30 发运，
20	 * 计划通过 p0 23:00、p1 23:30、p2 00:00、p3 00:30 → 运输窗口跨越禁行起点，须设置安全接力点。
21	 */
22	class RelayHandoverTest extends HazmatIntegrationTestBase {
23	
24	    private static final LocalDateTime DEPARTURE = LocalDateTime.parse("2026-10-02T22:30:00");
25	    private static final LocalDateTime CURFEW_START = LocalDateTime.parse("2026-10-03T00:00:00");
26	
27	    @BeforeEach
28	    void fixClock() {
29	        // 固定业务时钟于禁行起点前，避免真实时钟触发懒冻结。
30	        clock.setTime(LocalDateTime.parse("2026-10-02T22:30:00"));
31	    }
32	
33	    private String dispatched(String reqPrefix, String plate) {
34	        String no = shipmentNo(apply(reqPrefix + "-apply", plate, "FLAMMABLE", "R-G3", DEPARTURE));
35	        approve(no);
36	        dispatch(no, reqPrefix + "-dispatch");
37	        return no;
38	    }
39	
40	    private Map<String, Object> segmentOf(String shipmentNo, int relaySeq) {
41	        return relaySegments(view(shipmentNo)).stream()
42	                .filter(s -> Integer.valueOf(relaySeq).equals(s.get("relaySeq")))
43	                .findFirst().orElseThrow();
44	    }
45	
46	    @Test
47	    void relayRequiredAndDoubleCheckinCompletesHandover() {
48	        String no = dispatched("rh-main", "沪A-1001");
49	        // 运输窗口跨越禁行起点 → 须设置安全接力点。
50	        assertThat(view(no).get("relayRequired")).isEqualTo(true);
51	        assertThat(view(no).get("curfewStart")).isEqualTo(CURFEW_START.toString());
52	
53	        ServiceResult set = setRelayPoint(no, "rh-main-rp", 1);
54	        assertThat(set.httpStatus()).isEqualTo(200);
55	        assertThat(segmentOf(no, 1).get("status")).isEqualTo("IN_PROGRESS");
56	
57	        // 单人打卡不生效：仅交班一侧，换班未完成。
58	        ServiceResult out = relayCheckin(no, "rh-main-out", "ESC-01", "OUT",
59	                LocalDateTime.parse("2026-10-02T23:20:00"));
60	        assertThat(out.body().get("handoverCompleted")).isEqualTo(false);
61	        assertThat(segmentOf(no, 1).get("status")).isEqualTo("IN_PROGRESS");
62	
63	        // 接班打卡后换班完成：记录含双方编号与时刻。
64	        ServiceResult in = relayCheckin(no, "rh-main-in", "ESC-02", "IN",
65	                LocalDateTime.parse("2026-10-02T23:25:00"));
66	        assertThat(in.body().get("handoverCompleted")).isEqualTo(true);
67	        Map<String, Object> segment = segmentOf(no, 1);
68	        assertThat(segment.get("status")).isEqualTo("COMPLETED");
69	        assertThat(segment.get("outEscortId")).isEqualTo("ESC-01");
70	        assertThat(segment.get("outTime")).isEqualTo("2026-10-02T23:20");
71	        assertThat(segment.get("inEscortId")).isEqualTo("ESC-02");
72	        assertThat(segment.get("inTime")).isEqualTo("2026-10-02T23:25");
73	        assertThat(segment.get("completedAt")).isEqualTo("2026-10-02T23:25");
74	        assertThat(events(view(no)).stream()
75	                .anyMatch(e -> "RELAY_HANDOVER".equals(e.get("eventType")))).isTrue();
76	    }
77	
78	    @Test
79	    void sameEscortBothRolesRejectedAsSinglePerson() {
80	        String no = dispatched("rh-same", "沪A-1001");
81	        setRelayPoint(no, "rh-same-rp", 1);
82	        relayCheckin(no, "rh-same-out", "ESC-01", "OUT", LocalDateTime.parse("2026-10-02T23:20:00"));
83	        // 同一押运员打卡接班 → 单人打卡不生效，400。
84	        assertThatThrownBy(() -> relayCheckin(no, "rh-same-in", "ESC-01", "IN",
85	                LocalDateTime.parse("2026-10-02T23:25:00")))
86	                .isInstanceOf(ApiException.class)
87	                .satisfies(e -> assertThat(((ApiException) e).getCode()).isEqualTo("RELAY_SAME_ESCORT"));
88	        assertThat(segmentOf(no, 1).get("status")).isEqualTo("IN_PROGRESS");
89	        // 不同押运员接班后正常完成。
90	        relayCheckin(no, "rh-same-in2", "ESC-02", "IN", LocalDateTime.parse("2026-10-02T23:26:00"));
91	        assertThat(segmentOf(no, 1).get("status")).isEqualTo("COMPLETED");
92	    }
93	
94	    @Test
95	    void outOfOrderSubmissionOrderedByTime() {
96	        String no = dispatched("rh-ooo", "沪A-1002");
97	        setRelayPoint(no, "rh-ooo-rp", 1);
98	        // 接班打卡先回传（时刻 23:25），交班后回传（时刻 23:20）→ 按时刻归位，换班完成。
99	        ServiceResult in = relayCheckin(no, "rh-ooo-in", "ESC-02", "IN",
100	                LocalDateTime.parse("2026-10-02T23:25:00"));
101	        assertThat(in.body().get("handoverCompleted")).isEqualTo(false);
102	        ServiceResult out = relayCheckin(no, "rh-ooo-out", "ESC-01", "OUT",
103	                LocalDateTime.parse("2026-10-02T23:20:00"));
104	        assertThat(out.body().get("handoverCompleted")).isEqualTo(true);
105	        Map<String, Object> segment = segmentOf(no, 1);
106	        assertThat(segment.get("outTime")).isEqualTo("2026-10-02T23:20");
107	        assertThat(segment.get("inTime")).isEqualTo("2026-10-02T23:25");
108	    }
109	
110	    @Test
111	    void reverseCheckinRejectedAndAlerted() {
112	        String no = dispatched("rh-rev", "沪A-1001");
113	        setRelayPoint(no, "rh-rev-rp", 1);
114	        relayCheckin(no, "rh-rev-out", "ESC-01", "OUT", LocalDateTime.parse("2026-10-02T23:25:00"));
115	        // 接班时刻早于交班时刻 → 逆序拒绝并告警。
116	        assertThatThrownBy(() -> relayCheckin(no, "rh-rev-in-bad", "ESC-02", "IN",
117	                LocalDateTime.parse("2026-10-02T23:20:00")))
118	                .isInstanceOf(ApiException.class)
119	                .satisfies(e -> assertThat(((ApiException) e).getCode()).isEqualTo("RELAY_CHECKIN_REVERSED"));
120	        // 恰同时刻也不满足"严格晚于" → 逆序拒绝。
121	        assertThatThrownBy(() -> relayCheckin(no, "rh-rev-in-eq", "ESC-02", "IN",
122	                LocalDateTime.parse("2026-10-02T23:25:00")))
123	                .isInstanceOf(ApiException.class)
124	                .satisfies(e -> assertThat(((ApiException) e).getCode()).isEqualTo("RELAY_CHECKIN_REVERSED"));
125	        // 拒绝不产生打卡记录，告警事件独立保留。
126	        assertThat(segmentOf(no, 1).get("status")).isEqualTo("IN_PROGRESS");
127	        assertThat(events(view(no)).stream()
128	                .filter(e -> "RELAY_CHECKIN_REVERSED".equals(e.get("eventType"))).count()).isEqualTo(2);
129	        // 合法时刻重新打卡仍可完成换班。
130	        relayCheckin(no, "rh-rev-in-ok", "ESC-02", "IN", LocalDateTime.parse("2026-10-02T23:26:00"));
131	        assertThat(segmentOf(no, 1).get("status")).isEqualTo("COMPLETED");
132	    }
133	
134	    @Test
135	    void duplicateRoleAndRelayPointDedup() {
136	        String no = dispatched("rh-dup", "沪A-1002");
137	        setRelayPoint(no, "rh-dup-rp", 1);
138	        // 运单+途经点序号去重：同一途经点不可重复设置接力段。
139	        assertThatThrownBy(() -> setRelayPoint(no, "rh-dup-rp2", 1))
140	                .isInstanceOf(ApiException.class)
141	                .satisfies(e -> assertThat(((ApiException) e).getCode()).isEqualTo("RELAY_POINT_DUPLICATE"));
142	        // 同一运单同时刻只允许一个进行中接力段。
143	        assertThatThrownBy(() -> setRelayPoint(no, "rh-dup-rp0", 0))
144	                .isInstanceOf(ApiException.class)
145	                .satisfies(e -> assertThat(((ApiException) e).getCode()).isEqualTo("RELAY_SEGMENT_ACTIVE"));
146	        // 同一角色重复打卡（不同 requestId）→ 去重拒绝。
147	        relayCheckin(no, "rh-dup-out", "ESC-01", "OUT", LocalDateTime.parse("2026-10-02T23:20:00"));
148	        assertThatThrownBy(() -> relayCheckin(no, "rh-dup-out2", "ESC-09", "OUT",
149	                LocalDateTime.parse("2026-10-02T23:21:00")))
150	                .isInstanceOf(ApiException.class)
151	                .satisfies(e -> assertThat(((ApiException) e).getCode()).isEqualTo("RELAY_CHECKIN_DUPLICATE"));
152	        // 换班完成后释放占用：可设置新接力段。
153	        relayCheckin(no, "rh-dup-in", "ESC-02", "IN", LocalDateTime.parse("2026-10-02T23:25:00"));
154	        assertThat(setRelayPoint(no, "rh-dup-rp0b", 0).httpStatus()).isEqualTo(200);
155	    }
156	
157	    @Test
158	    void unsafeRelayPointRejected() {
159	        String no = dispatched("rh-unsafe", "沪B-2001");
160	        // p2 计划通过 00:00 恰为禁行起点，不早于起点 → 不能作为安全接力点。
161	        assertThatThrownBy(() -> setRelayPoint(no, "rh-unsafe-rp", 2))
162	                .isInstanceOf(ApiException.class)
163	                .satisfies(e -> assertThat(((ApiException) e).getCode()).isEqualTo("RELAY_POINT_UNSAFE"));
164	        // p1 计划通过 23:30 早于禁行起点 → 合法。
165	        assertThat(setRelayPoint(no, "rh-unsafe-rp1", 1).httpStatus()).isEqualTo(200);
166	    }
