168	    @Test
169	    void relayEndpointsAreIdempotent() {
170	        String no = dispatched("rh-idem", "沪A-1001");
171	        // 接力点设置：同键同参返回首次结果；同键异参 409。
172	        ServiceResult first = setRelayPoint(no, "rh-idem-rp", 1);
173	        ServiceResult replay = setRelayPoint(no, "rh-idem-rp", 1);
174	        // 重放结果经 JSON 存储，数值类型可能收窄，按字符串比对业务值。
175	        assertThat(String.valueOf(replay.body().get("relaySegmentId")))
176	                .isEqualTo(String.valueOf(first.body().get("relaySegmentId")));
177	        assertThatThrownBy(() -> setRelayPoint(no, "rh-idem-rp", 0))
178	                .isInstanceOf(ApiException.class)
179	                .satisfies(e -> assertThat(((ApiException) e).getCode())
180	                        .isEqualTo("IDEMPOTENT_FINGERPRINT_MISMATCH"));
181	        // 接力打卡：同键同参返回首次结果；同键异参 409。
182	        relayCheckin(no, "rh-idem-out", "ESC-01", "OUT", LocalDateTime.parse("2026-10-02T23:20:00"));
183	        ServiceResult inFirst = relayCheckin(no, "rh-idem-in", "ESC-02", "IN",
184	                LocalDateTime.parse("2026-10-02T23:25:00"));
185	        ServiceResult inReplay = relayCheckin(no, "rh-idem-in", "ESC-02", "IN",
186	                LocalDateTime.parse("2026-10-02T23:25:00"));
187	        assertThat(inReplay.body().get("handoverCompleted")).isEqualTo(true);
188	        assertThat(inReplay.body().get("handoverCompleted"))
189	                .isEqualTo(inFirst.body().get("handoverCompleted"));
190	        assertThatThrownBy(() -> relayCheckin(no, "rh-idem-in", "ESC-03", "IN",
191	                LocalDateTime.parse("2026-10-02T23:25:00")))
192	                .isInstanceOf(ApiException.class)
193	                .satisfies(e -> assertThat(((ApiException) e).getCode())
194	                        .isEqualTo("IDEMPOTENT_FINGERPRINT_MISMATCH"));
