    public RelayPointRequest(String requestId, int waypointSeq) {
        this(requestId, waypointSeq, null);
    }

    /** 归一化：缺省视为不启用。 */
    public boolean personnelControlEnabled() {
        return Boolean.TRUE.equals(personnelControl);
    }
}

