                .filter(s -> Integer.valueOf(1).equals(s.get("relaySeq"))).findFirst().orElseThrow();
        assertThat(segBView.get("status")).isEqualTo("IN_PROGRESS");
        assertThat(segBView.get("inEscortId")).isNull();
    }

