                                LocalDateTime.parse("2026-10-02T23:45:00"));
                        inOutcome.set(result.httpStatus() == 200 ? "COMPLETED" : "HTTP" + result.httpStatus());
                    } catch (ApiException e) {
                        inOutcome.set("REJECTED:" + e.getCode());
                    }
                });
                pool.submit(() -> {
                    await(start);
                    try {
